package com.bank.payments.service;

import com.bank.payments.model.Account;
import com.bank.payments.repository.AccountRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class TransferService {
    private static final Logger log = LoggerFactory.getLogger(TransferService.class);
    private final AccountRepository repo;

    public TransferService(AccountRepository repo) { this.repo = repo; }

    // SHORT transaction, timeout-guarded. If anything runs long, it is rolled back
    // and the connection is returned to the pool quickly — protecting other requests.
    @Transactional(timeout = 2)
    public void transfer(String fromId, String toId, BigDecimal amount) {
        Account rajesh = repo.findById(fromId).orElseThrow();
        Account priya = repo.findById(toId).orElseThrow();
        // NO external HTTP calls inside the transaction — that would hold the connection.
        rajesh.debit(amount);
        priya.credit(amount);
        repo.save(rajesh);
        repo.save(priya);
        log.info("Transfer {} from {} to {} completed", amount, fromId, toId);
    }
}
