package com.bank.payments.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class ReportService {
    private static final Logger log = LoggerFactory.getLogger(ReportService.class);
    private final JdbcTemplate jdbc;

    public ReportService(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    // Heavy aggregation marked readOnly so it can be routed to a read replica
    // and timeout-guarded so it cannot starve the primary's connection pool.
    @Transactional(readOnly = true, timeout = 5)
    public BigDecimal totalSettledForYear(int year) {
        log.info("Running yearly aggregation for {} (should run on replica)", year);
        return jdbc.queryForObject(
            "SELECT COALESCE(SUM(amount),0) FROM transactions " +
            "WHERE status='SETTLED' AND EXTRACT(YEAR FROM txn_date)=?",
            BigDecimal.class, year);
    }
}
